import React from 'react';
import './App.css';
import SubmitRequestForm from './components/SubmitRequestForm.tsx';
import RequestStatusDashboard from './components/RequestStatusDashboard.tsx';

function App() {
  return (
    <div className="App">
      <header className="App-header">
        <h1>Lifeline - Hospital Dashboard</h1>
      </header>
      <main className="container">
        <div className="form-section">
          <h2>Submit New Blood Request</h2>
          <SubmitRequestForm />
        </div>
        <div className="dashboard-section">
          <h2>Your Active Requests</h2>
          <RequestStatusDashboard />
        </div>
      </main>
    </div>
  );
}

export default App;
